import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"错误代码 — 完整的数值面","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/error-codes.md","filePath":"zh/troubleshooting/error-codes.md"}'),a={name:"zh/troubleshooting/error-codes.md"};function r(s,t,l,h,n,i){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="错误代码-—-完整的数值面" tabindex="-1">错误代码 — 完整的数值面 <a class="header-anchor" href="#错误代码-—-完整的数值面" aria-label="Permalink to &quot;错误代码 — 完整的数值面&quot;">​</a></h1><p>Open Cube OS <strong>没有全局 <code>errno</code></strong> 也没有 <code>errno.h</code> — freestanding 内核不链接 libc。通用约定是：</p><ul><li><strong>0 = 成功，负数 = 失败</strong>（<code>-1</code> 为通用；<code>Returns 0 on success, -1 on failure</code> 是文档化习语）。</li><li>需要精度的子系统使用<strong>稠密负数枚举</strong> — 8 个家族， <strong>共 61 个代码</strong>，下文逐一列出其触发场景与应对。</li><li>尺寸/长度返回 <code>-1</code>；环形缓冲读取越过窗口返回 <code>-1</code>； watchdog 槽位 API 返回 <strong>-1（表满）/ -2（参数错误）</strong>。</li><li>唯一的正数哨兵家族是崩溃来源伪向量 <code>OC_CRASH_SRC_*</code> (32..36)，它们搭载在 crashlog 记录的 <code>vector</code> 字段上。</li></ul><p>本页涉及的命令：<a href="./../manual/commands/dmesg.html">dmesg</a>、 <a href="./../manual/commands/logcat.html">logcat</a>、<a href="./../manual/commands/logctl.html">logctl</a>、 <a href="./../manual/commands/crashlog.html">crashlog</a>、<a href="./../manual/commands/health.html">health</a>、 <a href="./../manual/commands/update.html">update</a>、<a href="./../manual/commands/config.html">config</a>。</p><hr><h2 id="家族-1-—-oc-update-e-15-个代码-更新管线" tabindex="-1">家族 1 — OC_UPDATE_E_*（15 个代码，更新管线） <a class="header-anchor" href="#家族-1-—-oc-update-e-15-个代码-更新管线" aria-label="Permalink to &quot;家族 1 — OC_UPDATE_E_*（15 个代码，更新管线）&quot;">​</a></h2><p>定义于 <code>services/selfhost/interface/svc_selfhost_update.h</code>；在 <code>svc_selfhost_ab.c</code> / <code>svc_selfhost_update.c</code> 中解码为文本。这些是 每条 <code>update: ... failed: &lt;why&gt;</code> 行背后的代码。</p><table tabindex="0"><thead><tr><th>代码</th><th>值</th><th>含义</th><th>触发场景</th><th>应对</th></tr></thead><tbody><tr><td><code>OC_UPDATE_E_CONFIG</code></td><td>-1</td><td>配置文件缺失或不可读</td><td>/etc 卷上没有 <code>/etc/opencube.conf</code></td><td>检查 <code>config path</code>；/etc 卷是否已挂载？见 <a href="./storage-issues.html">storage-issues.md</a></td></tr><tr><td><code>OC_UPDATE_E_PREFIX</code></td><td>-2</td><td>URL 前缀非法（必须为 http:// 或 https://）</td><td><code>update_url</code> 拼写错误（<code>ftp://...</code>）</td><td><code>config get update_url</code>，用 <code>config set update_url http://...</code> 修正</td></tr><tr><td><code>OC_UPDATE_E_DNS</code></td><td>-3</td><td>DNS 解析失败</td><td>更新主机无法解析</td><td><code>dns &lt;host&gt;</code>；从 <code>dhcp</code>/<code>ip</code> 输出检查 DNS 服务器</td></tr><tr><td><code>OC_UPDATE_E_CONNECT</code></td><td>-4</td><td>连接失败</td><td>服务器不可达（路由/防火墙）</td><td><code>ping</code> 该主机，<code>route</code> 查看网关，<code>firewall</code> 列表</td></tr><tr><td><code>OC_UPDATE_E_TIMEOUT</code></td><td>-5</td><td>无响应（超时）</td><td>服务器未接受任何内容</td><td>重试；检查主机可达性</td></tr><tr><td><code>OC_UPDATE_E_HTTP</code></td><td>-6</td><td>HTTP 错误</td><td>服务器返回错误状态</td><td>检查服务器端 / URL 路径</td></tr><tr><td><code>OC_UPDATE_E_JSON</code></td><td>-7</td><td>JSON 解析失败</td><td>update.json 格式错误</td><td>用 <code>wget</code> 手动获取并阅读</td></tr><tr><td><code>OC_UPDATE_E_BUFSIZE</code></td><td>-8</td><td>响应过大</td><td>changes 列表溢出 128 字节缓冲</td><td>服务端修复（缩短 changes）</td></tr><tr><td><code>OC_UPDATE_E_DISABLED</code></td><td>-9</td><td>配置中 online_update=no</td><td>更新被配置禁用</td><td><code>config set online_update yes</code></td></tr><tr><td><code>OC_UPDATE_E_NOAB</code></td><td>-10</td><td>无 A/B 磁盘</td><td>未从 A/B 布局启动</td><td><code>update status</code>，然后创建：<code>abdisk &lt;dev&gt;</code>（destructive）</td></tr><tr><td><code>OC_UPDATE_E_SHA</code></td><td>-11</td><td>SHA256 校验失败</td><td>包损坏或被篡改</td><td>重新下载；检查 update.json 中的 <code>package_sha256</code></td></tr><tr><td><code>OC_UPDATE_E_TARGZ</code></td><td>-12</td><td>包不是有效的 gzip/tar</td><td>下载被截断</td><td>重新下载；核对大小</td></tr><tr><td><code>OC_UPDATE_E_IO</code></td><td>-13</td><td>文件系统 I/O 错误</td><td>/data 写入失败</td><td><code>df</code>，对卷执行 <code>fsck</code></td></tr><tr><td><code>OC_UPDATE_E_SLOT</code></td><td>-14</td><td>槽位非法（应为 A 或 B）</td><td>内部槽位运算失败</td><td>运行 <code>abcfg</code>；若持续出现则报告</td></tr><tr><td><code>OC_UPDATE_E_ARGS</code></td><td>-15</td><td>NULL / 畸形参数</td><td>内部调用方 bug</td><td>附确切命令行报告</td></tr></tbody></table><h2 id="家族-2-—-oc-gzip-err-13-个代码含-0-gunzip" tabindex="-1">家族 2 — OC_GZIP_ERR_*（13 个代码含 0，gunzip） <a class="header-anchor" href="#家族-2-—-oc-gzip-err-13-个代码含-0-gunzip" aria-label="Permalink to &quot;家族 2 — OC_GZIP_ERR_*（13 个代码含 0，gunzip）&quot;">​</a></h2><p><code>kernel/core_lib_gzip.h</code>（<code>ocse/kernel/lib/lib_gzip.h</code> 中有相同副本）。 由 OTA 包路径和每个 gzipped 注册表程序在 exec 时暴露 （应用解压）。</p><table tabindex="0"><thead><tr><th>代码</th><th>值</th><th>含义</th><th>触发</th><th>应对</th></tr></thead><tbody><tr><td><code>OC_GZIP_ERR_NONE</code></td><td>0</td><td>成功</td><td>—</td><td>—</td></tr><tr><td><code>OC_GZIP_ERR_ARGS</code></td><td>-1</td><td>NULL 指针 / 容量错误</td><td>API 误用</td><td>内部问题；报告</td></tr><tr><td><code>OC_GZIP_ERR_MAGIC</code></td><td>-2</td><td>不是 gzip 流（1f 8b）</td><td>文件不是 gzip</td><td>重新下载 / 重新压缩该包</td></tr><tr><td><code>OC_GZIP_ERR_METHOD</code></td><td>-3</td><td>CM != 8（deflate）</td><td>非 deflate 的 gzip</td><td>重建该包（<code>tools/make_update_pkg.sh</code>）</td></tr><tr><td><code>OC_GZIP_ERR_HEADER</code></td><td>-4</td><td>gzip 头畸形</td><td>头部被截断</td><td>重新下载</td></tr><tr><td><code>OC_GZIP_ERR_BLOCK</code></td><td>-5</td><td>块头 / 长度检查非法</td><td>流中段损坏</td><td>重新下载；先核对 SHA256</td></tr><tr><td><code>OC_GZIP_ERR_TABLE</code></td><td>-6</td><td>Huffman 表非法</td><td>deflate 表损坏</td><td>同上</td></tr><tr><td><code>OC_GZIP_ERR_DIST</code></td><td>-7</td><td>距离超出窗口</td><td>回引损坏</td><td>同上</td></tr><tr><td><code>OC_GZIP_ERR_TRUNC</code></td><td>-8</td><td>流在最终块前结束</td><td>尾部被截断</td><td>同上</td></tr><tr><td><code>OC_GZIP_ERR_CRC</code></td><td>-9</td><td>尾部 CRC32 不匹配</td><td>静默损坏</td><td>重新下载（这正是先检查 OC_UPDATE_E_SHA 的原因）</td></tr><tr><td><code>OC_GZIP_ERR_ISIZE</code></td><td>-10</td><td>尾部 ISIZE 不匹配</td><td>大小字段错误</td><td>同上</td></tr><tr><td><code>OC_GZIP_ERR_SINK</code></td><td>-11</td><td>sink 回调失败</td><td>输出设备出错</td><td>检查磁盘空间</td></tr><tr><td><code>OC_GZIP_ERR_STATE</code></td><td>-12</td><td>API 误用（finish 后继续 feed 等）</td><td>调用方 bug</td><td>内部问题；报告</td></tr></tbody></table><h2 id="家族-3-—-oc-tar-err-7-个代码-ustar" tabindex="-1">家族 3 — OC_TAR_ERR_*（7 个代码，ustar） <a class="header-anchor" href="#家族-3-—-oc-tar-err-7-个代码-ustar" aria-label="Permalink to &quot;家族 3 — OC_TAR_ERR_*（7 个代码，ustar）&quot;">​</a></h2><p><code>kernel/core_lib_tar.h</code>（+ ocse 孪生）。包安装的解包一半。</p><table tabindex="0"><thead><tr><th>代码</th><th>值</th><th>含义</th><th>触发</th><th>应对</th></tr></thead><tbody><tr><td><code>OC_TAR_ERR_ARGS</code></td><td>-1</td><td>NULL / 参数错误</td><td>API 误用</td><td>内部问题</td></tr><tr><td><code>OC_TAR_ERR_HEADER</code></td><td>-2</td><td>头块畸形 / 过短</td><td>归档损坏</td><td>重建该包</td></tr><tr><td><code>OC_TAR_ERR_CSUM</code></td><td>-3</td><td>头校验和不匹配</td><td>头损坏</td><td>重建；固定件中的 <code>ustar bad checksum rejected</code></td></tr><tr><td><code>OC_TAR_ERR_SIZE</code></td><td>-4</td><td>文件大小字段非法</td><td>非八进制大小字段</td><td>重建</td></tr><tr><td><code>OC_TAR_ERR_SINK</code></td><td>-5</td><td>文件回调失败</td><td>目标写入错误</td><td>磁盘满？<code>df</code></td></tr><tr><td><code>OC_TAR_ERR_STATE</code></td><td>-6</td><td>API 误用</td><td>调用方 bug</td><td>内部问题</td></tr><tr><td><code>OC_TAR_ERR_TRUNC</code></td><td>-7</td><td>归档在条目中途结束</td><td>包被截断</td><td>重新下载</td></tr></tbody></table><h2 id="家族-4-—-oc-config-e-5-个代码-etc-opencube-conf" tabindex="-1">家族 4 — OC_CONFIG_E_*（5 个代码，/etc/opencube.conf） <a class="header-anchor" href="#家族-4-—-oc-config-e-5-个代码-etc-opencube-conf" aria-label="Permalink to &quot;家族 4 — OC_CONFIG_E_*（5 个代码，/etc/opencube.conf）&quot;">​</a></h2><p><code>kernel/core_lib_config.h</code>（+ ocse 孪生）。位于 <code>config get/set</code> 与 配置后端之后。</p><table tabindex="0"><thead><tr><th>代码</th><th>值</th><th>含义</th><th>触发</th><th>应对</th></tr></thead><tbody><tr><td><code>OC_CONFIG_E_ARGS</code></td><td>-1</td><td>NULL / 参数错误</td><td>API 误用</td><td>内部问题</td></tr><tr><td><code>OC_CONFIG_E_NOFILE</code></td><td>-2</td><td>/etc/opencube.conf 缺失或不可读</td><td>无 /etc 卷，或首次启动</td><td><code>config path</code>；挂载 /etc；<code>config restore</code> 重建默认值</td></tr><tr><td><code>OC_CONFIG_E_NOKEY</code></td><td>-3</td><td>键未找到（或值为空）</td><td>键拼写错误</td><td><code>config list</code> 显示有效键</td></tr><tr><td><code>OC_CONFIG_E_TOOLONG</code></td><td>-4</td><td>值放不进输出缓冲</td><td>值过长</td><td>缩短该值</td></tr><tr><td><code>OC_CONFIG_E_IO</code></td><td>-5</td><td>VFS 读/写错误</td><td>卷错误</td><td><code>fsck</code>，重新挂载</td></tr></tbody></table><h2 id="家族-5-—-enc-e-5-个代码-gb2312-utf-8-转换" tabindex="-1">家族 5 — ENC_E_*（5 个代码，GB2312/UTF-8 转换） <a class="header-anchor" href="#家族-5-—-enc-e-5-个代码-gb2312-utf-8-转换" aria-label="Permalink to &quot;家族 5 — ENC_E_*（5 个代码，GB2312/UTF-8 转换）&quot;">​</a></h2><p><code>services/encoding/interface/svc_encoding_core.h</code>（+ ocse 孪生）。 由 CJK 控制台层和 <code>serial_encoding</code> 使用。</p><table tabindex="0"><thead><tr><th>代码</th><th>值</th><th>含义</th><th>触发</th><th>应对</th></tr></thead><tbody><tr><td><code>ENC_E_INVAL</code></td><td>-2</td><td>NULL 指针 / 零容量</td><td>API 误用</td><td>内部问题</td></tr><tr><td><code>ENC_E_TRUNC</code></td><td>-3</td><td>输入在序列中途结束</td><td>多字节输入被截断</td><td>检查发送方编码（<code>serial_encoding</code>）</td></tr><tr><td><code>ENC_E_ILLEGAL</code></td><td>-4</td><td>字节序列在该字符集中非法</td><td>GBK 字节被按 UTF-8 读取或反之</td><td><code>serial_encoding utf8|gbk</code> 与对端匹配</td></tr><tr><td><code>ENC_E_NOSPACE</code></td><td>-5</td><td>输出缓冲过小</td><td>超大转换</td><td>内部问题</td></tr><tr><td><code>ENC_E_UNMAP</code></td><td>-6</td><td>码点在目标中无映射</td><td>无 GB2312 映射的罕用汉字</td><td>无法避免；字体层会回退</td></tr></tbody></table><h2 id="家族-6-—-x509-e-8-个代码-ok-证书校验" tabindex="-1">家族 6 — X509_E_*（8 个代码 + OK，证书校验） <a class="header-anchor" href="#家族-6-—-x509-e-8-个代码-ok-证书校验" aria-label="Permalink to &quot;家族 6 — X509_E_*（8 个代码 + OK，证书校验）&quot;">​</a></h2><p><code>services/crypto/interface/svc_crypto_x509.h</code>；在 <code>svc_crypto_x509.c</code> 中解码。它们决定 HTTPS 连接的生死。</p><table tabindex="0"><thead><tr><th>代码</th><th>值</th><th>含义</th><th>触发</th><th>应对</th></tr></thead><tbody><tr><td><code>X509_OK</code></td><td>0</td><td>已校验</td><td>链锚定于内嵌根存储（ISRG Root X1 等）</td><td>—</td></tr><tr><td><code>X509_E_FORMAT</code></td><td>-1</td><td>证书格式错误</td><td>DER 畸形</td><td>服务端修复</td></tr><tr><td><code>X509_E_UNSUPPORTED</code></td><td>-2</td><td>不支持的算法</td><td>非 RSA 链</td><td>服务端修复</td></tr><tr><td><code>X509_E_EXPIRED</code></td><td>-3</td><td>证书已过期</td><td>服务器证书过期</td><td><code>rtc</code>（客户机时钟正常吗？）；然后服务端处理</td></tr><tr><td><code>X509_E_NOT_YET</code></td><td>-4</td><td>证书尚未生效</td><td>时钟在过去</td><td><code>rtc</code></td></tr><tr><td><code>X509_E_NO_ROOT</code></td><td>-5</td><td>签发者证书缺失</td><td>自签名或无锚链</td><td>默认拒绝（安全模型）；仅测试时可经 <code>config set tls.insecure 1</code> 显式选择加入</td></tr><tr><td><code>X509_E_BADSIG</code></td><td>-6</td><td>签名校验失败</td><td>证书被篡改</td><td>视为敌意；不要绕过</td></tr><tr><td><code>X509_E_HOSTNAME</code></td><td>-7</td><td>主机名不匹配</td><td>证书属于另一名字</td><td>修正 URL 或证书</td></tr><tr><td><code>X509_E_NO_ISSUER</code></td><td>-8</td><td>（保留/未知）</td><td>解码表回退打印 <code>unknown error</code></td><td>报告</td></tr></tbody></table><h2 id="家族-7-—-oc-usb-e-7-个代码-usb-传输" tabindex="-1">家族 7 — OC_USB_E*（7 个代码，USB 传输） <a class="header-anchor" href="#家族-7-—-oc-usb-e-7-个代码-usb-传输" aria-label="Permalink to &quot;家族 7 — OC_USB_E*（7 个代码，USB 传输）&quot;">​</a></h2><p><code>drivers/usb/drv_usb_core.h</code>（+ ocse 孪生）。每次 USB 传输都返回 其中之一。</p><table tabindex="0"><thead><tr><th>代码</th><th>值</th><th>含义</th><th>触发</th><th>应对</th></tr></thead><tbody><tr><td><code>OC_USB_ETIMEDOUT</code></td><td>-100</td><td>传输超时</td><td>设备停顿</td><td>重新插拔；<code>usb</code> 重新枚举</td></tr><tr><td><code>OC_USB_ENODEV</code></td><td>-101</td><td>无设备</td><td>设备已拔出</td><td>重新插拔；<code>usb_hotplug_test</code> 复现拔出路径</td></tr><tr><td><code>OC_USB_ESTALL</code></td><td>-102</td><td>端点停顿</td><td>设备拒绝请求</td><td>设备侧问题；<code>usb_storage_test</code> 显示 CSW 状态</td></tr><tr><td><code>OC_USB_EIO</code></td><td>-103</td><td>I/O 错误</td><td>总线错误</td><td>检查控制器（<code>usb</code>、<code>lspci</code>）</td></tr><tr><td><code>OC_USB_ENOMEM</code></td><td>-104</td><td>内存不足</td><td>分配失败</td><td><code>mem</code>/<code>free</code>；报告</td></tr><tr><td><code>OC_USB_EINVAL</code></td><td>-105</td><td>参数非法</td><td>API 误用</td><td>内部问题</td></tr><tr><td><code>OC_USB_ENAK</code></td><td>-106</td><td>NAK（尚未就绪）</td><td>设备忙</td><td>重试</td></tr></tbody></table><h2 id="家族-8-—-oc-power-e-unsupported-1-个代码" tabindex="-1">家族 8 — OC_POWER_E_UNSUPPORTED（1 个代码） <a class="header-anchor" href="#家族-8-—-oc-power-e-unsupported-1-个代码" aria-label="Permalink to &quot;家族 8 — OC_POWER_E_UNSUPPORTED（1 个代码）&quot;">​</a></h2><p><code>services/power/interface/svc_power_core.h</code>（+ ocse 孪生）：<code>-1</code> — &quot;走完所有端口后机器仍在运行&quot;。当关机遍历尝试了每个端口 （ACPI S5、端口 0x64、CF9）而机器仍活着时返回；用户看到 <code>Power off not supported. System halted.</code> — 在 VM 中请使用 宿主机的电源控制。</p><h3 id="解码文本表-字符串所在处" tabindex="-1">解码文本表（字符串所在处） <a class="header-anchor" href="#解码文本表-字符串所在处" aria-label="Permalink to &quot;解码文本表（字符串所在处）&quot;">​</a></h3><p>每个家族在调用点旁都有孪生的解码到文本表 —— 天然的 grep 锚点：<code>svc_selfhost_ab.c</code>（update）、 <code>svc_crypto_x509.c</code>（x509）、fs/block/net 服务中的 <code>put()</code> 字符串。SMBus i801 状态字解码为 <code>NACK/device error</code>、 <code>bus error/collision</code>、<code>transaction failed</code>、<code>timeout</code>。</p><hr><h2 id="_11-个-kernel-panic-调用点" tabindex="-1">11 个 kernel_panic 调用点 <a class="header-anchor" href="#_11-个-kernel-panic-调用点" aria-label="Permalink to &quot;11 个 kernel_panic 调用点&quot;">​</a></h2><p>panic 原因是<strong>拼装</strong>的而非字面量（在栈缓冲上用 strcpy/strcat/u64_to_str 构造），因此要 grep 常量 前缀，而不是整串。</p><table tabindex="0"><thead><tr><th>#</th><th>位置</th><th>原因串（格式）</th><th>触发</th></tr></thead><tbody><tr><td>1</td><td><code>arch_exceptions.c:203</code></td><td>透传 <code>&lt;reason&gt;</code></td><td>崩溃服务尚未注册时使用的架构回退 — 打印 <code>KERNEL PANIC (no crash handler installed): &lt;reason&gt;</code> + <code>System halted.</code></td></tr><tr><td>2</td><td><code>core_sched.c:658</code></td><td><code>kernel stack bounds violated on switch (task=&lt;name&gt;, rsp=0x&lt;hex&gt; window=[0x&lt;lo&gt;,0x&lt;hi&gt;])</code></td><td>调度器即将切换到的任务其保存的 RSP 位于其栈窗口之外（损坏/溢出）；它拒绝在陌生内存上恢复</td></tr><tr><td>3</td><td><code>svc_crash_core.c:563</code></td><td><code>watchdog timeout: no heartbeat for &lt;N&gt;s (task=&lt;name&gt;)</code></td><td>软件崩溃 watchdog 在 OC_WDT_TIMEOUT_MS 内未见心跳（默认 15 s；仅在启动后武装，节拍已注册但默认 DISARMED 以避免长 shell 命令期间的误 panic）</td></tr><tr><td>4</td><td><code>svc_crash_watchdog.c:451</code></td><td><code>watchdog timeout: &lt;N&gt;s without a feed (task=&lt;name&gt;)</code></td><td>策略为 PANIC 的已注册 watchdog 槽位超出预算（如 <code>watchdog test panic</code>）</td></tr><tr><td>5</td><td><code>svc_diag_l1.c:261</code></td><td><code>manual crashtest: kernel_panic()</code></td><td><code>crashtest panic</code> 命令</td></tr><tr><td>6</td><td><code>ocse/core_watchdog.c:450</code></td><td>（#4 的孪生）</td><td>OCSE 安装器内核 watchdog</td></tr><tr><td>7</td><td><code>ocse/core_sched.c:613</code></td><td>（#2 的孪生）</td><td>OCSE 调度器</td></tr><tr><td>8</td><td><code>ocse/core_crash.c:567</code></td><td><code>watchdog timeout: no shell heartbeat for &lt;N&gt;s</code></td><td>OCSE 软 watchdog</td></tr><tr><td>9</td><td><code>arch_exceptions.c:438+</code> (ocos)</td><td><code>KERNEL STACK OVERFLOW (guard page hit, task=&lt;name&gt;)</code></td><td>CR2 落在 kthread 守卫页内的 #PF</td></tr><tr><td>10</td><td>（孪生）</td><td><code>KERNEL STACK OVERFLOW (stack exhausted -&gt; #DF, task=&lt;name&gt;)</code></td><td>RSP 位于任务栈基之下或 ≥ 0x40000000000 的 #DF</td></tr><tr><td>11</td><td>（两棵树）</td><td><code>ring-0 exception &lt;N&gt; (&lt;#XX Name&gt;)</code></td><td>任何其他未处理的 ring-0 异常</td></tr></tbody></table><p>仅横幅式停机（无 panic 记录）：<code>PANIC: idle task stack allocation failed - halting</code>（调度器初始化 OOM — 两个内核皆有）。</p><h3 id="统一-panic-横幅-打印内容-按序" tabindex="-1">统一 panic 横幅（打印内容，按序） <a class="header-anchor" href="#统一-panic-横幅-打印内容-按序" aria-label="Permalink to &quot;统一 panic 横幅（打印内容，按序）&quot;">​</a></h3><p>在串口（权威）+ VGA（尽力而为）上：</p><ol><li><code>*** NESTED PANIC INSIDE PANIC - HALTING ***</code> — 一行，然后停机 （绝不递归）。</li><li>#DF 特例：<code>*** KERNEL PANIC: &lt;reason&gt; [task=&lt;name&gt;] ***</code> + <code>source: #DF Double Fault err=0x&lt;hex&gt; rip=0x&lt;hex&gt; handled at dispatcher depth]</code> + <code>core dump: skipped in #DF mode (see KNOWN_ISSUES)</code> + 策略行。</li><li>CR3 规范化；klog 环形 FATAL 记录；crashlog 记录（无文本）。</li><li><code>*** KERNEL PANIC: &lt;reason&gt; ***</code>（+ <code> [KERNEL STACK OVERFLOW: exhausted, task=&lt;name&gt;]</code> 注记）+ 内核版本/构建 + 来源 行（<code>manual/panic|watchdog-timeout|assertion-failed|contained(TUI)| kstack-overflow|exception &lt;N&gt;</code>）+ 任务 + 寄存器 + 回溯。</li><li>VGA 单行（原因截断到 90 字符）+ <code>Registers and call trace on the serial console.</code></li><li>核心转储状态：<code>core dump: UNAVAILABLE (no boot-time buffer)</code> 或 <code>&lt;N&gt; bytes captured, persisted to /var/crash/core.dump</code>（或串口 回退 / <code>persist FAILED</code>）。</li><li>L1 panic 处理链：<code>*** panic handler claimed recovery - resuming ***</code>（罕见 — TUI 崩溃防护是唯一用户）。</li><li>日志刷写状态：<code>crash log: &lt;n&gt; bytes to /var/log/crash.log; klog flushed &lt;n&gt; bytes to /var/log/kernel.log</code>（或 FAILED 变体）。</li><li>策略：<code>policy: HALT|REBOOT - system stopped (safe halt loop)| - rebooting NOW</code>。</li></ol><h3 id="崩溃来源伪名-crashlog-vector-字段-32-36" tabindex="-1">崩溃来源伪名（crashlog <code>vector</code> 字段 32..36） <a class="header-anchor" href="#崩溃来源伪名-crashlog-vector-字段-32-36" aria-label="Permalink to &quot;崩溃来源伪名（crashlog `vector` 字段 32..36）&quot;">​</a></h3><p><code>manual/panic</code>、<code>watchdog-timeout</code>、<code>assertion-failed</code>、 <code>contained(TUI)</code>、<code>kstack-overflow</code>、回退 <code>exception</code>。记录中的 x86 向量名：<code>#DE Divide Error</code>、<code>#DB Debug</code>、<code>#BP Breakpoint</code>、<code>#OF Overflow</code>、<code>#BR Bound Range Exceeded</code>、<code>#UD Invalid Opcode</code>、<code>#NM Device Not Available</code>、<code>#DF Double Fault</code>、<code>#TS Invalid TSS</code>、<code>#NP Segment Not Present</code>、<code>#SS Stack-Segment Fault</code>、<code>#GP General Protection</code>、<code>#PF Page Fault</code>、<code>#MF x87 FPU Error</code>、<code>#AC Alignment Check</code>、<code>#MC Machine Check</code>、<code>#XM SIMD FP Exception</code>、<code>#SX Security Exception</code>、回退 <code>Unknown</code>。</p><hr><h2 id="_30-个-static-assert-防护" tabindex="-1">30 个 <code>_Static_assert</code> 防护 <a class="header-anchor" href="#_30-个-static-assert-防护" aria-label="Permalink to &quot;30 个 `_Static_assert` 防护&quot;">​</a></h2><p>全部是编译期布局契约 — 漂移<strong>令构建失败</strong>，绝不会 在运行时发生。如果你撞上一个，说明跨模块 ABI 的两侧 不再一致：</p><table tabindex="0"><thead><tr><th>防护</th><th>位置</th><th>契约</th></tr></thead><tbody><tr><td><code>ocst_u32 must be 4 bytes</code> / <code>ocst_state_t layout drifted</code> / <code>ocst_record_t layout drifted</code></td><td><code>include/ocbl_state.h</code></td><td>OCBL↔OCOS↔OCIRE 跨引导邮箱（0x98000/0x9B000）</td></tr><tr><td><code>regs struct layout drift</code></td><td><code>ocbl/bios/ocbl_bios.h</code></td><td>BIOS 寄存器帧</td></tr><tr><td><code>ehdr layout</code> / <code>phdr layout</code></td><td><code>ocbl/common/ocbl_load.c</code></td><td>OCBL 解析的 ELF 头</td></tr><tr><td><code>task_t.fpu_state offset must match OFF_FPU in arch_context_switch.S</code>（+ <code>fpu_saved</code>、<code>rflags</code> 孪生）</td><td><code>ocos/core_sched.c</code> <strong>与</strong> <code>ocse/core_sched.c</code>（各 3 个）</td><td>调度器↔asm 上下文切换 ABI</td></tr><tr><td><code>registry empty</code></td><td><code>ocos/core_usermode.c</code></td><td>编译进内核的应用注册表</td></tr><tr><td><code>chinese_font gz layout mismatch - regenerate chinese_font_data.c</code></td><td><code>services/font/svc_font_chinese.c</code></td><td>内嵌 CJK 字体 blob</td></tr><tr><td>8 个 UHCI 调度页重叠防护：<code>ISO TD overlaps int QH</code>、<code>int QH overlaps ctrl QH</code>、<code>ctrl QH overlaps ctrl TDs</code>、<code>ctrl TD pool overlaps bulk QH</code>、<code>bulk QH overlaps bulk TDs</code>、<code>bulk TD pool overlaps int TDs</code>、<code>int TD pool overlaps scratch</code>、<code>scratch overflows schedule page</code></td><td><code>drivers/usb/drv_usb_core.c</code> <strong>与</strong> ocse 孪生（各 8 个）</td><td>UHCI 帧表布局数学</td></tr></tbody></table><hr><h2 id="日志格式-—-解读输出" tabindex="-1">日志格式 — 解读输出 <a class="header-anchor" href="#日志格式-—-解读输出" aria-label="Permalink to &quot;日志格式 — 解读输出&quot;">​</a></h2><h3 id="klog-dmesg-logcat" tabindex="-1">klog（dmesg / logcat） <a class="header-anchor" href="#klog-dmesg-logcat" aria-label="Permalink to &quot;klog（dmesg / logcat）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[&lt;seconds&gt;.&lt;mmm padded to 3&gt;] &lt;LEVEL padded to 6&gt; &lt;module&gt;: &lt;message&gt;</span></span></code></pre></div><p>示例：<code>[ 12.345] ERROR watchdog: watchdog slot 3 (net-rx) -&gt; KILL task</code>。</p><p>级别：<code>DEBUG</code> 0、<code>INFO</code> 1、<code>WARN</code> 2、<code>ERROR</code> 3、<code>FATAL</code> 4。环形 容纳 1024 条；覆盖计入 <code>klog_dropped()</code>， <code>dmesg</code> 显示页脚 <code>-- &lt;shown&gt; lines (ring &lt;n&gt;/1024, dropped &lt;d&gt;) --</code>。用 <code>logcat -l &lt;level&gt;</code>（debug..fatal 或 0-4）、<code>-m &lt;module&gt;</code>、<code>-k &lt;keyword&gt;</code>、<code>-t &lt;seconds&gt;</code>、<code>-n &lt;count&gt;</code> 过滤； <code>-f</code> 跟随。级别过滤陷阱见 <a href="./silent-failures.html">silent-failures.md</a>。</p><h3 id="引导阶段日志" tabindex="-1">引导阶段日志 <a class="header-anchor" href="#引导阶段日志" aria-label="Permalink to &quot;引导阶段日志&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[HH:MM:SS.mmm] &lt;stage&gt;: OK|FAIL</span></span></code></pre></div><p>安静级别 1 抑制非 FAIL 行；任何 <code>FAIL</code> 子串都为引导状态 判定标记失败。阶段名（OCST 阶梯）： <code>BOOT</code>、<code>KM_AIN_ENTERED</code>、<code>SCHED_READY</code>、<code>DRIVERS_READY</code>、 <code>SERVICES_READY</code>、<code>L1_LAUNCHED</code>、<code>L1_READY</code>，运行时标记 255 = <code>RUNTIME</code>。</p><h3 id="健康告警-klog-warn-类" tabindex="-1">健康告警（klog WARN 类） <a class="header-anchor" href="#健康告警-klog-warn-类" aria-label="Permalink to &quot;健康告警（klog WARN 类）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alarm: memory &gt;90% used (&lt;used&gt;/&lt;total&gt; KiB)</span></span>\n<span class="line"><span>alarm: &lt;n&gt; active tasks (&gt;64)</span></span>\n<span class="line"><span>alarm: CPU &gt;=90% busy for 10 consecutive seconds</span></span></code></pre></div><p>机器&quot;感觉不对&quot;时第一个要运行的就是 <code>health</code> 命令 — 见 <a href="./silent-failures.html">silent-failures.md</a>。</p><h3 id="崩溃记录" tabindex="-1">崩溃记录 <a class="header-anchor" href="#崩溃记录" aria-label="Permalink to &quot;崩溃记录&quot;">​</a></h3><p><code>crashlog</code> 列出 32 条环形记录（字段：jiffies、rtc_epoch、vector、 ring、error_code、rip、rsp、cr2、tid、pid、task[16]）；刷写到 <code>/var/log/crash.log</code>；核心转储落在 <code>/var/crash/core.dump</code>；klog 刷写到 <code>/var/log/kernel.log</code>。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./error-catalog.html">error-catalog.md</a> — 按子系统罗列每条消息串， 附排查链</li><li><a href="./silent-failures.html">silent-failures.md</a> — 完全不打印任何内容的 失败</li><li><a href="./../manual/hidden-commands.html">../manual/hidden-commands.md</a> — 刻意演练这些路径的测试桩</li><li><a href="./../arch/crash-recovery.html">../arch/crash-recovery.md</a> — panic 机制设计</li></ul>',60)])])}const g=d(a,[["render",r]]);export{p as __pageData,g as default};
